namespace UnityEngine;
public class Object{public bool Destroyed;public static implicit operator bool(Object o)=>!ReferenceEquals(o,null)&&!o.Destroyed;public static bool operator==(Object a,Object b)=>ReferenceEquals(a,b)||(!a&&!b);public static bool operator!=(Object a,Object b)=>!(a==b);public override bool Equals(object o)=>ReferenceEquals(this,o);public override int GetHashCode()=>System.Runtime.CompilerServices.RuntimeHelpers.GetHashCode(this);}
public class Component:Object{}
public class Behaviour:Component{public bool enabled{get;set;}=true;}
public class GameObject:Object{}
public struct Vector3{
 public float x,y,z;public Vector3(float x,float y,float z){this.x=x;this.y=y;this.z=z;}public static Vector3 zero=>new();public static Vector3 one=>new(1,1,1);public static Vector3 up=>new(0,1,0);public float sqrMagnitude=>x*x+y*y+z*z;public static Vector3 operator+(Vector3 a,Vector3 b)=>new(a.x+b.x,a.y+b.y,a.z+b.z);public static Vector3 operator-(Vector3 a,Vector3 b)=>new(a.x-b.x,a.y-b.y,a.z-b.z);public static Vector3 operator-(Vector3 a)=>new(-a.x,-a.y,-a.z);public static Vector3 operator*(Vector3 a,float b)=>new(a.x*b,a.y*b,a.z*b);public static Vector3 operator/(Vector3 a,float b)=>new(a.x/b,a.y/b,a.z/b);public static bool operator==(Vector3 a,Vector3 b)=>(a-b).sqrMagnitude<1e-12;public static bool operator!=(Vector3 a,Vector3 b)=>!(a==b);public override bool Equals(object o)=>o is Vector3 b&&this==b;public override int GetHashCode()=>HashCode.Combine(x,y,z);public static Vector3 Scale(Vector3 a,Vector3 b)=>new(a.x*b.x,a.y*b.y,a.z*b.z);public System.Numerics.Vector3 N=>new(x,y,z);public static Vector3 From(System.Numerics.Vector3 v)=>new(v.X,v.Y,v.Z);
}
public struct Quaternion{
 internal System.Numerics.Quaternion q;public static Quaternion identity=>new(){q=System.Numerics.Quaternion.Identity};public static Quaternion Euler(Vector3 v)=>new(){q=System.Numerics.Quaternion.CreateFromYawPitchRoll(v.y*MathF.PI/180,v.x*MathF.PI/180,v.z*MathF.PI/180)};public static Quaternion Inverse(Quaternion v)=>new(){q=System.Numerics.Quaternion.Inverse(v.q)};public static Quaternion operator*(Quaternion a,Quaternion b)=>new(){q=a.q*b.q};public static Vector3 operator*(Quaternion a,Vector3 v)=>Vector3.From(System.Numerics.Vector3.Transform(v.N,a.q));public static float Angle(Quaternion a,Quaternion b){var dot=Math.Clamp(MathF.Abs(System.Numerics.Quaternion.Dot(System.Numerics.Quaternion.Normalize(a.q),System.Numerics.Quaternion.Normalize(b.q))),0,1);return 2*MathF.Acos(dot)*180/MathF.PI;}
 public Vector3 eulerAngles{get{var n=System.Numerics.Quaternion.Normalize(q);float pitch=MathF.Asin(Math.Clamp(2*(n.W*n.X-n.Y*n.Z),-1,1));float yaw=MathF.Atan2(2*(n.W*n.Y+n.Z*n.X),1-2*(n.X*n.X+n.Y*n.Y));float roll=MathF.Atan2(2*(n.W*n.Z+n.X*n.Y),1-2*(n.X*n.X+n.Z*n.Z));return new(pitch*180/MathF.PI,yaw*180/MathF.PI,roll*180/MathF.PI);}}
}
public class Transform:Object{
 public Transform parent{get;set;}public Vector3 localPosition{get;set;}public Quaternion localRotation{get;set;}=Quaternion.identity;public Vector3 localScale{get;set;}=Vector3.one;public Vector3 localEulerAngles{get=>localRotation.eulerAngles;set=>localRotation=Quaternion.Euler(value);}public Vector3 lossyScale=>parent?Vector3.Scale(parent.lossyScale,localScale):localScale;public Quaternion rotation{get=>parent?parent.rotation*localRotation:localRotation;set=>localRotation=parent?Quaternion.Inverse(parent.rotation)*value:value;}public Vector3 position{get=>parent?parent.TransformPoint(localPosition):localPosition;set=>localPosition=parent?parent.InverseTransformPoint(value):value;}public Vector3 TransformPoint(Vector3 v)=>position+rotation*Vector3.Scale(lossyScale,v);public Vector3 InverseTransformPoint(Vector3 v){var n=Quaternion.Inverse(rotation)*(v-position);var s=lossyScale;return new(n.x/s.x,n.y/s.y,n.z/s.z);}public Vector3 TransformVector(Vector3 v)=>rotation*Vector3.Scale(lossyScale,v);public bool IsChildOf(Transform t){for(var p=parent;p;p=p.parent)if(p==t)return true;return false;}
}
